`timescale 10ns/1ns

/////////////////////////////////////////////
// addroundkey
//   New State =  state bitwise-XORed with roundkey
//		(roundkey is an input, generated by keyexpansion externally)
//   Section 5.1.4, Figure 5
//   Purely combinational
/////////////////////////////////////////////

module addroundkey(input  logic [127:0] state0,
				  input logic [127:0] roundkey,
                 output logic [127:0] state1);
	assign state1 = state0^roundkey;
endmodule